import{_ as a,o as t,c as n,a5 as o}from"./chunks/framework.QnCkLuYX.js";const i="/assets/license-request.VXUB54jV.png",r="/assets/license-active.O5kRu93y.png",g=JSON.parse('{"title":"License Management","description":"","frontmatter":{},"headers":[],"relativePath":"en_US/09-license-management.md","filePath":"en_US/09-license-management.md"}'),s={name:"en_US/09-license-management.md"};function l(c,e,d,h,p,m){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="license-management" tabindex="-1">License Management <a class="header-anchor" href="#license-management" aria-label="Permalink to &quot;License Management&quot;">​</a></h1><p>Request and install an offline license, confirm export availability, and handle renewal or computer replacement.</p><h2 id="what-you-can-do-on-this-page" tabindex="-1">What you can do on this page <a class="header-anchor" href="#what-you-can-do-on-this-page" aria-label="Permalink to &quot;What you can do on this page&quot;">​</a></h2><ul><li>Understand which functions require a license.</li><li>Save user information and copy the displayed machine code.</li><li>Install a license code or file.</li><li>Review the registered user, expiration date, and status.</li><li>Renew, remove, or troubleshoot a license.</li></ul><h2 id="understand-license-scope" tabindex="-1">Understand license scope <a class="header-anchor" href="#understand-license-scope" aria-label="Permalink to &quot;Understand license scope&quot;">​</a></h2><p>GridSubStudio uses a locally verified, time-limited license for final project subtitle <strong>Export</strong> only:</p><ul><li>Without a valid license, you can still create/open projects, import resources, edit and save, run quality checks, and use machine translation.</li><li>The <strong>Export Wizard</strong> still opens for configuration and preview, but its final <strong>Export</strong> button is disabled.</li><li>A license does not alter the project format or write data into <code>project.json</code>, <code>workspace.csv</code>, or the project folder.</li></ul><p>The top bar shows <strong>Trial</strong>, <strong>Licensed</strong>, or <strong>Expired</strong>. For troubleshooting, use the complete message in <strong>Settings → License</strong>.</p><h2 id="get-a-machine-code" tabindex="-1">Get a machine code <a class="header-anchor" href="#get-a-machine-code" aria-label="Permalink to &quot;Get a machine code&quot;">​</a></h2><ol><li>Open <strong>Settings → License</strong>.</li><li>Enter the name and email that should appear on the license.</li><li>Click <strong>Save</strong>.</li><li>When <strong>Machine Code</strong> appears, click <strong>Copy</strong>.</li><li>Send the name, email, and complete code through the <a href="/en_US/contact.html">contact page</a>.</li></ol><p><img src="'+i+'" alt="Manage License before activation, with user information and machine code"></p><p>Keep the submitted name and email unchanged while the request is being processed, and do not publish the machine code.</p><h2 id="add-a-license" tabindex="-1">Add a license <a class="header-anchor" href="#add-a-license" aria-label="Permalink to &quot;Add a license&quot;">​</a></h2><p>The provider may supply either a pasteable code or a <code>.gss-license</code> file. The file picker also accepts <code>.json</code> or <code>.txt</code> when they contain the same provider-supplied license document.</p><p>To use a code, paste the complete value into <strong>Add License</strong> and click <strong>Add License</strong>. To use a file, click <strong>Choose File</strong>, select the original file, and wait for validation.</p><p>Validation occurs locally and does not require an account login or license-server connection. Do not edit the code or file; use it exactly as supplied.</p><h2 id="confirm-activation" tabindex="-1">Confirm activation <a class="header-anchor" href="#confirm-activation" aria-label="Permalink to &quot;Confirm activation&quot;">​</a></h2><p>A successful license shows <strong>Licensed</strong>, the registered name/email, and expiration date.</p><p><img src="'+r+'" alt="Licensed state with registered user, expiration date, and Remove License"></p><p>The user-information, machine-code, and add-license sections are hidden while a recognized license is installed. Close the dialog and open Export Wizard to confirm the final Export button is available.</p><p>A license also covers a maximum GridSubStudio version. If the installed app is newer than the licensed version, export is disabled even when the date has not expired; request an updated license.</p><h2 id="renew-a-license" tabindex="-1">Renew a license <a class="header-anchor" href="#renew-a-license" aria-label="Permalink to &quot;Renew a license&quot;">​</a></h2><ol><li>Note the registered user and expiration date.</li><li>Contact the provider through the <a href="/en_US/contact.html">contact page</a> before expiration.</li><li>Obtain the replacement license.</li><li>Click <strong>Remove License</strong> to reveal the installation controls.</li><li>Install the new code/file and confirm status again.</li></ol><p>Removing the current license disables final subtitle export until replacement succeeds. Save the project and obtain the new license before replacing one near a delivery deadline.</p><p>Up to 24 hours of grace may follow the signed expiration time. Rely on the current status message and Export button, and do not plan delivery around the grace period.</p><h2 id="move-to-another-computer" tabindex="-1">Move to another computer <a class="header-anchor" href="#move-to-another-computer" aria-label="Permalink to &quot;Move to another computer&quot;">​</a></h2><p>An old computer&#39;s license normally cannot be used directly on a new computer. On the new computer, open <strong>Settings → License</strong>, save the correct name/email, copy the displayed machine code, and request a new license through the <a href="/en_US/contact.html">contact page</a>. Project files can be moved through the normal backup/migration process.</p><h2 id="remove-a-license" tabindex="-1">Remove a license <a class="header-anchor" href="#remove-a-license" aria-label="Permalink to &quot;Remove a license&quot;">​</a></h2><p><strong>Remove License</strong> deletes the locally installed license and restores the request controls. It does not delete projects, subtitles, videos, exports, settings, or the original license file. It may not release a seat in the provider&#39;s system; follow the provider&#39;s process when seat recovery is required.</p><h2 id="protect-license-information" tabindex="-1">Protect license information <a class="header-anchor" href="#protect-license-information" aria-label="Permalink to &quot;Protect license information&quot;">​</a></h2><ul><li>Do not publish a complete license code, file, or machine code.</li><li>Do not put license files in project folders, shared packages, repositories, or diagnostics attachments.</li><li>Support usually needs the status message, app version, and expiration date. Redact codes unless a trusted private channel explicitly requires them.</li><li>Inspect attachments before sending them.</li></ul><h2 id="troubleshoot-license-problems" tabindex="-1">Troubleshoot license problems <a class="header-anchor" href="#troubleshoot-license-problems" aria-label="Permalink to &quot;Troubleshoot license problems&quot;">​</a></h2><h3 id="no-machine-code-appears" tabindex="-1">No machine code appears <a class="header-anchor" href="#no-machine-code-appears" aria-label="Permalink to &quot;No machine code appears&quot;">​</a></h3><p>Enter name/email and click <strong>Save</strong>. Reopen the dialog if necessary. If it remains empty, record the app version and visible error message.</p><h3 id="a-code-or-file-cannot-be-added" tabindex="-1">A code or file cannot be added <a class="header-anchor" href="#a-code-or-file-cannot-be-added" aria-label="Permalink to &quot;A code or file cannot be added&quot;">​</a></h3><p>Confirm the code is complete and was not truncated by chat/email. Use the original <code>.gss-license</code>, <code>.json</code>, or <code>.txt</code> from the provider without editing it.</p><h3 id="identity-or-machine-mismatch" tabindex="-1">Identity or machine mismatch <a class="header-anchor" href="#identity-or-machine-mismatch" aria-label="Permalink to &quot;Identity or machine mismatch&quot;">​</a></h3><p>Confirm the provider issued the license for the current computer and submitted information. After moving computers or changing registration details, copy the currently displayed code and contact the provider through the <a href="/en_US/contact.html">contact page</a>.</p><h3 id="license-is-expired" tabindex="-1">License is expired <a class="header-anchor" href="#license-is-expired" aria-label="Permalink to &quot;License is expired&quot;">​</a></h3><p>Check the displayed expiration date and request renewal. Editing and saving remain available after export is disabled.</p><h3 id="export-stopped-after-an-app-update" tabindex="-1">Export stopped after an app update <a class="header-anchor" href="#export-stopped-after-an-app-update" aria-label="Permalink to &quot;Export stopped after an app update&quot;">​</a></h3><p>The license may not cover the installed version. Request a license covering the current version; do not edit license data or system time.</p><h3 id="licensed-but-export-is-still-disabled" tabindex="-1">Licensed but Export is still disabled <a class="header-anchor" href="#licensed-but-export-is-still-disabled" aria-label="Permalink to &quot;Licensed but Export is still disabled&quot;">​</a></h3><p>Reopen Export Wizard and confirm the license dialog says <strong>Licensed</strong>. Then check for exportable rows, an ASS source template, filename conflicts, and output-folder permissions. See <a href="./07-saving-and-exporting.html#troubleshooting">Saving and Exporting</a>.</p>',44)])])}const f=a(s,[["render",l]]);export{g as __pageData,f as default};
